function usarSinSync(){
  // SEGURIDAD: Solo superadmin puede usar modo sin sync
  // Verificar si ya hay sesión activa con rol superadmin
  loadLocalDB();
  const isSARole=()=>{
    // En el flujo de setup aún no hay CU; permitir solo si ya hay usuarios SA en DB
    const hasSA=DB.usuarios.some(u=>u.rol==='superadmin');
    return !hasSA; // Si no hay usuarios creados (primera vez), permitir
  };
  if(CU&&CU.rol!=='superadmin'){
    toast('🔒 Modo sin sync solo disponible para SuperAdmin','var(--red)',4000);
    return;
  }
  const motivo=prompt('⚠️ MODO SIN SYNC — Solo para emergencias.\n\nEscribe el MOTIVO para activar el modo offline (quedará registrado):');
  if(!motivo||motivo.trim().length<5){
    toast('Debes indicar un motivo (mínimo 5 caracteres)','var(--amber)',4000);
    return;
  }
  // Registrar en localStorage con timestamp y motivo
  const logEntry={ts:new Date().toISOString(),user:CU?.nombre||'(setup)',rol:CU?.rol||'–',motivo:motivo.trim(),ua:navigator.userAgent.slice(0,120)};
  try{
    const prevLog=JSON.parse(localStorage.getItem('cu1_noSyncLog')||'[]');
    prevLog.unshift(logEntry);
    localStorage.setItem('cu1_noSyncLog',JSON.stringify(prevLog.slice(0,50)));
  }catch(e){}
  // También al auditLog si DB disponible
  if(DB&&CU){logAudit('sin_sync_activado','sesion','Modo offline activado. Motivo: '+motivo.trim());}
  localStorage.setItem('cu1_noSync','1');
  fbConnected=false;
  document.getElementById('setupWrap').style.display='none';
  setSyncStatus('off');
  showLogin();
}







