(function(){
  const params=new URLSearchParams(window.location.search);
  const trackId=params.get('track');
  if(!trackId)return;
  // Hide entire app, show tracking view
  document.querySelectorAll('body > *').forEach(el=>el.style.display='none');
  const wrap=document.createElement('div');
  wrap.id='trackingApp';
  document.body.appendChild(wrap);
  // Load DB
  loadLocalDB();
  // Try Firebase
  const fbUrl=localStorage.getItem('cu1_fbUrl');
  const fbK=localStorage.getItem('cu1_fbKey')||'controlunificado';
  let trkFbRef=null;
  if(fbUrl){
    try{
      const app=firebase.initializeApp({databaseURL:fbUrl},'trk_'+Date.now());
      const db=firebase.database(app);
      trkFbRef=db.ref('cu1/'+fbK);
      trkFbRef.on('value',snap=>{
        const rem=snap.val();if(!rem)return;
        if(rem.ingresos)DB.ingresos=Array.isArray(rem.ingresos)?rem.ingresos:Object.values(rem.ingresos);
        if(rem.ingresos2)DB.ingresos2=Array.isArray(rem.ingresos2)?rem.ingresos2:Object.values(rem.ingresos2);
        if(rem.eventos)DB.eventos=Array.isArray(rem.eventos)?rem.eventos:Object.values(rem.eventos);
        if(rem.usuarios)DB.usuarios=Array.isArray(rem.usuarios)?rem.usuarios:Object.values(rem.usuarios);
        renderTracking();
      });
    }catch(e){console.log('Firebase err:',e);}
  }

  let trkUser=null;
  let trkSessionExpiry=0;
  let undoTimer=null;

  function findIng(){
    // Only use manual override if QR trackId doesn't match any ingreso
    const id8=trackId.toLowerCase();
    const byQr=[...DB.ingresos,...(DB.ingresos2||[])].find(i=>i.id?.slice(0,8).toLowerCase()===id8);
    if(byQr){window._trkManualIng=null;return byQr;}
    if(window._trkManualIng)return window._trkManualIng;
    return null;
  }

  function saveTrkDB(){
    saveLocalDB();
    if(trkFbRef){
      trkFbRef.update({
        ingresos:DB.ingresos,
        ingresos2:DB.ingresos2||[]
      });
    }
  }

  function renderTracking(){
    const ing=findIng();
    if(!ing){wrap.innerHTML=trkPage('❌ Ingreso no encontrado','<p style="color:#64748b;font-size:12px">ID: '+trackId+'</p><p style="margin-top:10px;font-size:13px;color:#64748b">El código no corresponde a ningún vehículo registrado.</p><div style="margin-top:16px"><p style="font-size:13px;font-weight:700;margin-bottom:8px">🔍 Buscar por matrícula:</p><input id="trkManualMat" data-i18n-ph="phPlateExample" placeholder="Ej: AB-1234-CD" style="width:100%;padding:10px;border:1.5px solid #cbd5e1;border-radius:8px;font-size:14px;font-family:monospace;text-transform:uppercase;margin-bottom:8px" oninput="this.value=this.value.toUpperCase()"><button onclick="trkSearchManual()" style="width:100%;padding:12px;border:none;border-radius:20px;background:#4a5568;color:#fff;font-size:14px;font-weight:800;cursor:pointer">'+tr('buscarVehiculo')+'</button></div>');
    window.trkSearchManual=function(){const mat=(document.getElementById('trkManualMat').value||'').trim().toUpperCase();if(!mat)return;const found=(DB.ingresos||[]).find(x=>x.matricula===mat&&!x.salida)||(DB.ingresos2||[]).find(x=>x.matricula===mat&&!x.salida);if(found){window._trkManualIng=found;renderTracking();}else{document.getElementById('trkManualMat').style.borderColor='#8b3a3a';setTimeout(()=>{if(document.getElementById('trkManualMat'))document.getElementById('trkManualMat').style.borderColor='#cbd5e1';},1500);}};
    return;}
    const ev=ing.eventoId?DB.eventos.find(e=>e.id===ing.eventoId):null;
    const trk=ing.tracking||[];
    const lastStep=trk.length?trk[trk.length-1]:null;
    const isTerminado=lastStep?.stepId==='terminado';
    const isAuth=trkUser&&Date.now()<trkSessionExpiry;
    const canUndo=isAuth&&lastStep&&!isTerminado&&(Date.now()-new Date(lastStep.ts).getTime()<10000);

    // Status color
    let stBg='#eff6ff',stBorder='#4a5568',stColor='#4a5568';
    if(isTerminado){stBg='#e8ede8';stBorder='#4a5568';stColor='#4a5568';}
    else if(lastStep?.stepId==='en_espera'){stBg='#fef9c3';stBorder='#ca8a04';stColor='#a16207';}

    const stepInfo=s=>TRACKING_STEPS.find(x=>x.id===s)||{ico:'📍',name:s};
    const curStep=lastStep?stepInfo(lastStep.stepId):{ico:'🅿️',name:'Registrado'};

    let html=`<div style="max-width:420px;margin:0 auto;padding:16px;font-family:'Segoe UI',system-ui,sans-serif">
      <div style="background:#1e293b;color:#fff;padding:14px;border-radius:10px;margin-bottom:10px;text-align:center">
        <div style="font-size:28px;font-weight:900;font-family:'Courier New',monospace;letter-spacing:4px">${ing.matricula}</div>
        <div style="font-size:11px;opacity:.7;margin-top:4px">Pos. ${ing.pos||'–'} · ${ing.empresa||'–'} · Hall ${(ing.halls||[ing.hall||'']).join('/')}</div>
      </div>`;

    // Auth banner
    if(isAuth){
      html+=`<div style="background:#e8ede8;border:1.5px solid #86efac;border-radius:8px;padding:6px 10px;margin-bottom:8px;display:flex;align-items:center;gap:4px">
        <span>✅</span><span style="font-size:11px;font-weight:700;color:#4a5568">Operario: ${trkUser.nombre} · ${Math.round((trkSessionExpiry-Date.now())/60000)} min</span>
      </div>`;
    }

    // Status
    html+=`<div style="background:${stBg};border:2px solid ${stBorder};border-radius:8px;padding:10px;text-align:center;margin-bottom:10px">
      <div style="font-size:14px;font-weight:800;color:${stColor};letter-spacing:1.5px">${curStep.ico} ${curStep.name.toUpperCase()}</div>
      ${lastStep?`<div style="font-size:9px;color:#64748b;margin-top:2px">${new Date(lastStep.ts).toLocaleTimeString(undefined,{hour:'2-digit',minute:'2-digit'})} ${lastStep.user?'· '+lastStep.user:''}</div>`:''}
    </div>`;

    // Undo banner
    if(canUndo){
      const secsLeft=Math.max(0,10-Math.round((Date.now()-new Date(lastStep.ts).getTime())/1000));
      html+=`<div style="background:#fffbeb;border:1.5px solid #fde68a;border-radius:8px;padding:8px 10px;margin-bottom:10px;display:flex;align-items:center;gap:4px">
        <span>↩️</span><span style="flex:1;font-size:10px;color:#92400e;font-weight:700">¿Error? Deshacer: ${curStep.name}</span>
        <button onclick="trkUndo()" style="background:#4a5568;color:#fff;border:none;border-radius:20px;padding:4px 10px;font-size:10px;font-weight:700;cursor:pointer">↩ Deshacer</button>
        <span style="font-size:9px;color:#94a3b8;font-weight:700">${secsLeft}s</span>
      </div>`;
    }

    // Timeline
    html+=`<div style="padding-left:4px;margin-bottom:6px">`;
    trk.forEach((s,i)=>{
      const si=stepInfo(s.stepId);
      const isLast=i===trk.length-1;
      html+=`<div style="display:flex;align-items:flex-start;gap:10px;position:relative">
        ${!isLast?'<div style="position:absolute;left:13px;top:26px;bottom:-2px;width:2px;background:#86efac"></div>':''}
        <div style="width:28px;height:28px;border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:12px;background:#4a5568;flex-shrink:0;z-index:1;background:${isLast&&!isTerminado?'#e8eaed;border:2px solid #4a5568':'#4a5568;border:2px solid #3a4558'}">${isLast&&!isTerminado?'●':'✓'}</div>
        <div style="flex:1;padding:4px 0 14px">
          <div style="font-size:12px;font-weight:700">${si.ico} ${si.name}${s.note?' — '+s.note:''}</div>
          <div style="font-size:9px;color:#94a3b8">${new Date(s.ts).toLocaleTimeString(undefined,{hour:'2-digit',minute:'2-digit'})}${s.user?' · '+s.user:''}</div>
        </div>
      </div>`;
    });
    html+=`</div>`;

    // Actions (only if auth and not terminated)
    if(isAuth&&!isTerminado){
      const availSteps=TRACKING_STEPS.filter(s=>!s.fixed&&!s.end);
      html+=`<div style="font-size:11px;font-weight:700;color:#64748b;margin-bottom:6px">Registrar paso:</div><div style="display:flex;flex-wrap:wrap;gap:6px;margin-bottom:4px">
        ${availSteps.map(s=>`<button onclick="trkSelectStep('${s.id}')" id="trkOpt_${s.id}" style="padding:9px 12px;border-radius:20px;font-size:11px;font-weight:700;border:2px solid #e2e8f0;background:#4a5568;color:#475569;cursor:pointer;flex:1;min-width:110px;text-align:center">${s.ico} ${s.name}</button>`).join('')}
        </div>
        <button id="trkConfirmBtn" onclick="trkConfirmStep()" style="width:100%;padding:12px;border:none;border-radius:20px;font-size:13px;font-weight:800;cursor:pointer;background:#4a5568;color:#94a3b8;margin-bottom:6px" disabled>${tr('selPaso')}</button>
        <button onclick="trkModifyData()" style="width:100%;padding:10px;border:1px solid #e2e8f0;border-radius:20px;font-size:12px;font-weight:700;background:#4a5568;color:#64748b;cursor:pointer;margin-bottom:10px">📝 Modificar datos</button>
        <button onclick="trkEndDialog()" style="width:100%;padding:14px;border:3px solid #8b3a3a;border-radius:20px;background:#8b3a3a;color:#fff;font-size:13px;font-weight:900;cursor:pointer;letter-spacing:1px">⚠️ FINALIZAR SERVICIO</button>`;
    } else if(!isAuth&&!isTerminado){
      html+=`<button onclick="trkShowPin()" style="width:100%;padding:14px;border:none;border-radius:20px;background:#4a5568;color:#fff;font-size:14px;font-weight:800;cursor:pointer">🔓 Operario — Ingresa PIN para modificar</button>`;
    } else if(isTerminado){
      html+=`<div style="background:#f1f5f9;border-radius:8px;padding:14px;text-align:center">
        <div style="font-size:13px;font-weight:700;color:#94a3b8">🔒 Tracking cerrado</div>
        <div style="font-size:10px;color:#94a3b8;margin-top:4px">Solo un Supervisor puede reabrir desde la app</div>
      </div>`;
    }

    html+=`<div style="text-align:center;font-size:9px;color:#94a3b8;margin-top:16px">${ev?.nombre||'BeUnifyT'} · Fira Barcelona</div></div>`;
    wrap.innerHTML=html;

    // Auto-refresh undo timer
    if(canUndo){
      clearTimeout(undoTimer);
      undoTimer=setTimeout(renderTracking,1000);
    }
  }

  window._trkSelectedStep=null;
  window.trkSelectStep=function(stepId){
    window._trkSelectedStep=stepId;
    const si=TRACKING_STEPS.find(s=>s.id===stepId);
    document.querySelectorAll('[id^="trkOpt_"]').forEach(b=>{
      b.style.background=b.id==='trkOpt_'+stepId?'#4a5568':'#f8fafc';
      b.style.color=b.id==='trkOpt_'+stepId?'#fff':'#475569';
      b.style.borderColor=b.id==='trkOpt_'+stepId?'#4a5568':'#e2e8f0';
    });
    const btn=document.getElementById('trkConfirmBtn');
    if(btn){btn.disabled=false;btn.style.background='#4a5568';btn.style.color='#f7f7f7';btn.textContent='✓ Registrar: '+si.ico+' '+si.name;}
  };

  window.trkConfirmStep=function(){
    if(!window._trkSelectedStep||!trkUser)return;
    const si=TRACKING_STEPS.find(s=>s.id===window._trkSelectedStep);
    const ing=findIng();if(!ing)return;
    if(!confirm('¿Confirmar cambio a '+si.ico+' '+si.name+' para '+ing.matricula+'?'))return;
    if(!ing.tracking)ing.tracking=[];
    ing.tracking.push({stepId:si.id,ts:new Date().toISOString(),user:trkUser.nombre});
    saveTrkDB();
    window._trkSelectedStep=null;
    renderTracking();
  };

  window.trkEndDialog=function(){
    const ing=findIng();if(!ing)return;
    const r1=confirm('⚠️ FINALIZAR SERVICIO\n\nVehículo: '+ing.matricula+'\nEmpresa: '+(ing.empresa||'–')+'\n\nEsta acción cierra el tracking.\nNo se podrán registrar más pasos.\n\n¿Continuar?');
    if(!r1)return;
    const r2=confirm('🔒 CONFIRMAR FINALIZACIÓN\n\n¿Estás seguro de que '+ing.matricula+' ha completado TODAS las operaciones?\n\nEsta acción es irreversible desde el QR.');
    if(!r2)return;
    if(!ing.tracking)ing.tracking=[];
    ing.tracking.push({stepId:'terminado',ts:new Date().toISOString(),user:trkUser.nombre});
    saveTrkDB();
    renderTracking();
  };

  window.trkUndo=function(){
    const ing=findIng();if(!ing||!ing.tracking?.length)return;
    const last=ing.tracking[ing.tracking.length-1];
    if(Date.now()-new Date(last.ts).getTime()>10000){alert('⏰ Tiempo de deshacer expirado');renderTracking();return;}
    if(!confirm('↩ Deshacer paso: '+last.stepId+'?'))return;
    ing.tracking.pop();
    saveTrkDB();
    renderTracking();
  };

  window.trkModifyData=function(){
    alert('📝 Para modificar datos del ingreso, usa la app completa de BeUnifyT.\n\nEsta función estará disponible próximamente.');
  };

  window.trkShowPin=function(){
    let pin='';
    const html=`<div style="max-width:420px;margin:0 auto;padding:16px;font-family:'Segoe UI',system-ui,sans-serif">
      <div style="text-align:center;margin-bottom:16px"><span style="font-size:40px">🔐</span></div>
      <div style="text-align:center;font-size:14px;font-weight:800;margin-bottom:6px">${tr('ingresaPin')}</div>
      <div id="trkPinDots" style="display:flex;justify-content:center;gap:10px;margin-bottom:16px">
        <div class="pd"></div><div class="pd"></div><div class="pd"></div><div class="pd"></div><div class="pd"></div><div class="pd"></div>
      </div>
      <div id="trkPinErr" style="display:none;text-align:center;color:#8b3a3a;font-size:12px;font-weight:700;margin-bottom:8px">${tr('pinIncorrecto')}</div>
      <div style="display:grid;grid-template-columns:repeat(3,1fr);gap:8px;max-width:240px;margin:0 auto">
        ${[1,2,3,4,5,6,7,8,9,'',0,'⌫'].map(k=>k===''?'<div></div>':`<button onclick="trkPinKey('${k}')" style="padding:16px;border-radius:20px;background:#fff;border:1.5px solid #e2e8f0;font-size:20px;font-weight:800;cursor:pointer">${k}</button>`).join('')}
      </div>
      <button onclick="renderTracking()" style="width:100%;max-width:240px;margin:12px auto 0;display:block;padding:10px;border:1px solid #e2e8f0;border-radius:20px;font-size:12px;font-weight:700;background:#4a5568;color:#64748b;cursor:pointer">← Volver</button>
      <style>.pd{width:16px;height:16px;border-radius:50%;border:2px solid #cbd5e1;background:#fff}.pd.f{background:#4a5568;border-color:#3a4558}</style>
    </div>`;
    wrap.innerHTML=html;

    window.trkPinKey=function(k){
      if(k==='⌫'){pin=pin.slice(0,-1);}
      else if(pin.length<6){pin+=k;}
      // Update dots
      document.querySelectorAll('#trkPinDots .pd').forEach((d,i)=>d.className='pd'+(i<pin.length?' f':''));
      document.getElementById('trkPinErr').style.display='none';
      if(pin.length===6){
        const u=DB.usuarios.find(x=>x.pin===pin);
        if(u){
          trkUser=u;
          trkSessionExpiry=Date.now()+30*60*1000;
          renderTracking();
        }else{
          document.getElementById('trkPinErr').style.display='block';
          pin='';
          document.querySelectorAll('#trkPinDots .pd').forEach(d=>d.className='pd');
        }
      }
    };
  };

  function trkPage(title,body){
    return`<div style="max-width:420px;margin:0 auto;padding:40px 16px;font-family:'Segoe UI',system-ui,sans-serif;text-align:center">
      <div style="font-size:24px;font-weight:800;margin-bottom:6px">${title}</div>${body}</div>`;
  }

  renderTracking();
})();

