// ── Patch saveUser to handle empresa rol ──
// When rol=empresa is saved, link or create empresa record
var _origSaveUser=typeof saveUser==='function'?saveUser:null;
// We patch via the existing saveUser — add post-save hook
var _origSaveDB_eu=saveDB;
// Actually patch at the renderUsuarios level — simpler: extend openUserModal to show empId field for empresa rol
var _ouMOrig=openUserModal;
openUserModal=function(id){
  _ouMOrig(id);
  // After modal opens, if rol is empresa show empresa link info
  setTimeout(function(){
    var rolSel=document.getElementById('fuRol');
    if(!rolSel)return;
    var updateEmpInfo=function(){
      var rol=rolSel.value;
      var existing=document.getElementById('fuEmpInfo');
      if(existing)existing.remove();
      if(rol==='empresa'){
        var u=id?DB.usuarios.find(function(x){return x.id===id;}):null;
        var emp=u?(DB.empresas||[]).find(function(e){return e.id===u.empId||e.email===u.email;}):null;
        var info=document.createElement('div');
        info.id='fuEmpInfo';
        info.style.cssText='margin-top:8px;padding:8px 12px;background:var(--gll);border:1px solid var(--glb);border-radius:var(--r);font-size:11px;color:#065f46';
        info.innerHTML='🏢 <b>'+tr('thRole')+':</b> '+tr('roleCompanyInfo')+' al Portal de Empresas. '
          +(emp?'Empresa vinculada: <b>'+esc(emp.nombre)+'</b> ('+esc(emp.cif||'')+')'
               :'<span style="color:var(--amber)">⚠️ No hay empresa vinculada. El email del usuario debe coincidir con el de una empresa registrada, o créala primero desde el Portal.</span>');
        var foot=document.querySelector('#mUser .ffoot');
        if(foot)foot.parentNode.insertBefore(info,foot);
      }
    };
    rolSel.addEventListener('change',updateEmpInfo);
    updateEmpInfo();
  },100);
};

// ═══════════════════════════════════════════════════════
//  AUTOCOMPLETADO REFERENCIA → absorbe preregistro
//  Se inyecta en el formulario de ingreso de la web principal
// ═══════════════════════════════════════════════════════

window.pAutocompletarRefEnRampa=pAutocompletarRefEnRampa;

// Hook into the referencia field in the main ingreso form
setTimeout(function(){
  var refField=document.getElementById('fiRef');
  if(refField&&!refField._v6hooked){
    refField._v6hooked=true;
    refField.addEventListener('blur',function(){pAutocompletarRefEnRampa(this.value);});
    refField.addEventListener('change',function(){pAutocompletarRefEnRampa(this.value);});
  }
  // Also hook llamador field — when a llamador is typed, check if there's a preregistro
  var llamField=document.getElementById('fiLlamador');
  if(llamField&&!llamField._v6hooked){
    llamField._v6hooked=true;
    llamField.addEventListener('blur',function(){pAutocompletarRefEnRampa(this.value);});
  }
},2000);

// Also hook when the ingreso form opens (renderIngresos calls rebuild)
var _origOpenIng=typeof openIng==='function'?openIng:null;
if(_origOpenIng){
  openIng=function(){
    _origOpenIng.apply(this,arguments);
    setTimeout(function(){
      var rf=document.getElementById('fiRef');
      if(rf&&!rf._v6hooked){
        rf._v6hooked=true;
        rf.addEventListener('blur',function(){pAutocompletarRefEnRampa(this.value);});
      }
    },300);
  };
}

